-----
-- 1) Staging area: its own schema, created once
CREATE SCHEMA IF NOT EXISTS stg;

CREATE TABLE IF NOT EXISTS stg.order_items (
    order_id        text,
    order_item_id   int,
    product_id      text,
    seller_id       text,
    price           numeric,
    freight_value   numeric
);

CREATE TABLE IF NOT EXISTS stg.orders (
    order_id                  text,
    customer_id               text,
    order_status              text,
    order_purchase_timestamp  timestamp
);

-- 2) Data-quality log (never truncated: keeps history)
CREATE TABLE IF NOT EXISTS public.dq_report (
    run_at      timestamptz,
    table_name  text,
    check_name  text,
    value       bigint
);

-- 3) Empty everything that is rebuilt on every run
TRUNCATE TABLE public.fact_order_item,
               public.dim_product, public.dim_customer, public.dim_seller,
               public.dim_category, public.dim_geography, public.dim_date,
               stg.order_items, stg.orders;

-- 4) Natural keys must be unique inside each dimension
CREATE UNIQUE INDEX IF NOT EXISTS uq_dim_customer_id   ON public.dim_customer  (customer_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dim_seller_id     ON public.dim_seller    (seller_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dim_product_id    ON public.dim_product   (product_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dim_category_pt   ON public.dim_category  (category_name_pt);
CREATE UNIQUE INDEX IF NOT EXISTS uq_dim_geography_zip ON public.dim_geography (zip_prefix);

-- Script: quality_checks
--   Linked service: ls_pg_olap   |   Script type: NonQuery
-- ---------------------------------------------------------------
DO $$
DECLARE
    n bigint;
    raw_items bigint; dup_items bigint; raw_orders bigint;
BEGIN
    SELECT sum(value) FILTER (WHERE table_name = 'order_items' AND check_name = 'raw_rows'),
           sum(value) FILTER (WHERE table_name = 'order_items' AND check_name = 'duplicate_item_key'),
           sum(value) FILTER (WHERE table_name = 'orders'      AND check_name = 'raw_rows')
      INTO raw_items, dup_items, raw_orders
    FROM public.dq_report
    WHERE run_at = (SELECT max(run_at) FROM public.dq_report);

    IF raw_items IS NULL OR dup_items IS NULL OR raw_orders IS NULL THEN
        RAISE EXCEPTION 'dq_report is missing order_items.raw_rows, order_items.duplicate_item_key or orders.raw_rows';
    END IF;

    -- Stage 3: staging received every source row
    SELECT count(*) INTO n FROM stg.order_items;
    IF n <> raw_items THEN
        RAISE EXCEPTION 'stg.order_items has % rows, source has %', n, raw_items;
    END IF;
    SELECT count(*) INTO n FROM stg.orders;
    IF n <> raw_orders THEN
        RAISE EXCEPTION 'stg.orders has % rows, source has %', n, raw_orders;
    END IF;

    -- Stage 4: fact lost nothing
    SELECT count(*) INTO n FROM public.fact_order_item;
    IF n <> raw_items - dup_items THEN
        RAISE EXCEPTION 'fact_order_item has % rows, expected %', n, raw_items - dup_items;
    END IF;

    -- Stage 4: every key resolved against a real dimension row where one exists
    SELECT count(*) INTO n
    FROM public.fact_order_item f
    JOIN stg.orders o ON o.order_id = f.order_id
    JOIN public.dim_customer c ON c.customer_id = o.customer_id
    WHERE f.customer_key = -1;
    IF n > 0 THEN
        RAISE EXCEPTION '% fact rows got Unknown customer although the customer exists', n;
    END IF;

    SELECT count(*) INTO n FROM public.fact_order_item
    WHERE item_total <> round(price + freight_value, 2);
    IF n > 0 THEN RAISE EXCEPTION 'item_total wrong on % rows', n; END IF;
END $$;
